            gridFormat.addNumberColumn({ name: "radek_uhr", caption: "jres:31302370" });//RC 31302370 : Řád. úhr
            gridFormat.addTextColumn({ name: "zp_txt", caption: "jres:31302121" }); //RC 31302121 : Způsob platby
