            gridFormat.addTextColumn({ name: "ac", caption: "jres:31302371" }); //RC 31302371 : Agendové č.
            gridFormat.addTextColumn({ name: "wflspid_nazev", caption: "jres:31302372" });  //RC 31302372 : Agendový popis
