    export class SubContentPoplatnici extends GContent {


        icon = "gi-zverejnit"; //ikona do postranniho panelu
        title = "Napojení poplatníci"; //popisek do tooltipu postranniho panelu
        uid = "GNapojeniPoplatnici#";

        private gridPoplatnici: JQuery<HTMLElement>;
       

        prepareContent(inputParams): void {        

            let that = this;

            that.gridPoplatnici =              //vytvoreni gridu + definice                
                $("<div>")//vytvoreni elementu pro grid
                    .appendTo(this.element)
                    .gautofit()
                    .ggrid<Hpl.Interface.GPokBankPlatbyDto>({
                        data: [],   // this.modelPolozky[0]   //zatim nemam zadna data, nastavim prazdne pole. V momente nacteni je nastavim pres options (metoda loadJsGrid)
                        renderMode: "paged-async",     // auto, all-at-once, paged-sync, paged-async
                        columnMode: "full",      // fit, full
                        navigationMode: "row",  // row, cell
                        scrollHelperTemplate: "{ixs_esu}",
                        //   searchColumns: ["mjm"],
                        rowNumbers: true,
                        // multi: true,
                        columns: that["gridFormat"]
                    });


            this.defaultForm = that.gridPoplatnici;

        }

        refresh(ixpPlatbaRow: Hpl.Interface.GPokBankPlatbyDto): void {

            var that = this;

            if (!that.isActive())
                return;

            if (ixpPlatbaRow === undefined)
                return;

            that.beginOperation("Načítání poplatníků")

                        that.isl.PokBankPlatby.list(rq => {
                            return {
                                filters: {
                                    xxx_neplatny_esu: true,
                                    ixp_pl_vcetne: ixpPlatbaRow.ixp
                                }
                            }
                        }).get()
                            .done(function (data) {

                               
                                that.gridPoplatnici.ggrid("setData", data.data);
                                that.endOperation();
                              
                            })
                            .fail(function () {

                                that.endOperation();
                            });

        }

        /** Vola se v momente zobrazeni (klidne i vicekrat) */
        onActivate(): void {
            console.log("onActivate - poplatnici");
            
        }

        onDeactivate(): void {
            console.log("onDeactivate - poplatnici");
        }
           
    }

    export class SubContentSaldo extends GContent {


        icon = "gi-zverejnit"; //ikona do postranniho panelu
        title = "Saldo"; //popisek do tooltipu postranniho panelu
        uid = "GSaldo#";

        private lastPlatbaRow: Hpl.Interface.GPokBankPlatbyDto;



        /** Vola se jednou pri inicializaci (asynchronne) */
        prepareContent(inputParams): void {

            let that = this;

            var formSaldo = new Gordic.Forms.Form({ name: "pokSaldo" })
                //  .addSection("jres:31302396") //RC 31302396 : Saldo případu DDP
                .addRow("jres:31302397") //RC 31302397 : Datum salda
                .addField("gdatebox", {
                    name: "saldo_datum",
                    initialValue: new Date(this.globalSettings!.get("Pok.Nastaveni.DatSaldaDdp")),
                    disabled: true,
                    change: function (ev, changeObj) {

                        that.globalSettings!.set("Pok.Nastaveni.DatSaldaDdp", changeObj.value);                      
                        that.refresh(that.lastPlatbaRow);
                    }
                })
                .addRow("jres:31302398") //RC 31302398 : Saldo
                .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "saldo_castka", redNegative: true, disabled: true })
                .addRow("jres:31302399") //RC 31302399 : Vč. napoj. případů
                .addField("gcheck", {
                    name: "saldo_napoj",
                    initialValue: this.globalSettings!.get("Pok.OcekavanePlatby.Napojene"),
                    change: function (ev, changeObj) {

                        if (changeObj.value) {                           
                          that.findForms("pokSaldo").findFields("saldo_poplatnik").gcheck("setValue", false);
                        }

                        that.globalSettings!.set("Pok.OcekavanePlatby.Napojene", changeObj.value);

                        that.refresh(that.lastPlatbaRow);
                    }
                    ,
                    disabled: true
                })
                .addRow("jres:31302400") //RC 31302400 : Převzít na položku
                .addField("gcheck", {
                    name: "saldo_polozku",
                    initialValue: this.globalSettings!.get("Pok.OcekavanePlatby.Polozka"),
                    change: function (ev, changeObj) {
                      

                        that.globalSettings!.set("Pok.OcekavanePlatby.Polozka", changeObj.value);
                        that.refresh(that.lastPlatbaRow);
                    },
                    disabled: true
                })
                .addRow("jres:31302401") //RC 31302401 : Převzít poplatníky
                .addField("gcheck", {
                    name: "saldo_poplatnik",
                    initialValue: this.globalSettings!.get("Pok.OcekavanePlatby.Poplatniky"),
                    change: function (ev, changeObj) {


                        if (changeObj.value) {                           
                            that.findForms("pokSaldo").findFields("saldo_napoj").gcheck("setValue", false);
                        }
                        that.globalSettings!.set("Pok.OcekavanePlatby.Poplatniky", changeObj.value);
                        that.refresh(that.lastPlatbaRow);

                    },
                    disabled: true
                })
                .addRow({ label: "" }).addField("gradio", {
                    name: "saldo_radiaky",
                    itemClass: "",
                    initialValue: this.globalSettings!.get("Pok.OcekavanePlatby.Saldo") != null ? this.globalSettings!.get("Pok.OcekavanePlatby.Saldo") : true,
                    disabled: true,
                    change: function (ev, changeObj) {
                 
                        that.globalSettings!.set("Pok.OcekavanePlatby.Saldo", changeObj.value);
                        that.refresh(that.lastPlatbaRow);
                    },
                    radios: [
                        { value: 'false', label: 'Účetní saldo' },
                        { value: 'true', label: 'Splátkové saldo' },

                    ]
                });

            this.defaultForm = $.newDiv()
                .appendTo(this.element)
                .gform("createFrom", formSaldo);
        }


        refresh(ixpPlatbaRow: Hpl.Interface.GPokBankPlatbyDto): void {

            var that = this;


            if (!that.isActive())
                return;

            if (ixpPlatbaRow === undefined)
                return;

                //nenapadá mě nic jiného
                //než si tady dát poslední řádek
                //a když dojde ke změně na formuláři salda
                //tak to zavolat s ním
                //ať se saldo přepočítá
             
            that.lastPlatbaRow = ixpPlatbaRow;

            //var panel = that.element.gsidebar("getPanel", "sideBarSaldo");
            var panel = this.findForms("pokSaldo");

            if (panel === undefined)
                return;
          

            var datumSalda = panel.findFields("saldo_datum").gfield("getValue");
            var napojeniPoplatnici = panel.findFields("saldo_napoj").gfield("getValue");
            var splatkoveSaldo = panel.findFields("saldo_radiaky").gfield("getValue");

            if (ixpPlatbaRow != null && ixpPlatbaRow.ixp !== null && ixpPlatbaRow.typ_ag === 350) {

                panel.findFields("saldo_datum").gfield("option", "disabled", false);
                panel.findFields("saldo_napoj").gfield("option", "disabled", false);
                panel.findFields("saldo_polozka").gfield("option", "disabled", false);
                panel.findFields("saldo_poplatnik").gfield("option", "disabled", false);
                panel.findFields("saldo_radiaky").gfield("option", "disabled", false);
                panel.findFields("saldo_polozku").gfield("option", "disabled", false);


                that.beginOperation("Načítání salda")

                //dopočítání salda
                that.isl.PokBankPlatby.listPripadyDdp(rq => {
                    return {
                        filters: {
                            ixp: ixpPlatbaRow.ixp,
                            splatkove_saldo: splatkoveSaldo,
                            napojene_pripady: napojeniPoplatnici,
                            dat_do: datumSalda

                        },
                        fragments: ["SALDO", "*"]
                    }
                }).get().then(function (data) {

                    panel.findFields("saldo_castka").gfield("setValue", data.data[0].c_saldo);

                })
                    .always(function () {

                        that.endOperation();
                    })



            }
            else {

                panel.findFields("saldo_castka").gfield("setValue", 0);
                panel.findFields("saldo_datum").gfield("option", "disabled", true);
                panel.findFields("saldo_napoj").gfield("option", "disabled", true);
                panel.findFields("saldo_polozka").gfield("option", "disabled", true);
                panel.findFields("saldo_poplatnik").gfield("option", "disabled", true);
                panel.findFields("saldo_radiaky").gfield("option", "disabled", true);
                panel.findFields("saldo_polozku").gfield("option", "disabled", true);
            }


        }

     
        /** Vola se v momente zobrazeni (klidne i vicekrat) */
        onActivate(): void { console.log("onActivate - saldo"); }

        onDeactivate(): void { console.log("onDeactivate - saldo"); }

    }

